import math
def rational_reduce(numerator, denominator):
    if denominator == 0:
        raise ValueError("Zero denominator")
    gcd = math.gcd(numerator, denominator)
    num = numerator // gcd
    den = denominator // gcd
    if den < 0:
        num = -num
        den = -den
    return (num, den)
